import FDC_MAP from './fdc-map.json';
import FDC from './fdc-nutrients.json';
import type { Aisle, Allergen, FoodGroup, Ingredient, Nutrients } from './types';

/*
 * Nutrition: exact per-100 g values from USDA FoodData Central (SR Legacy), one record
 * per ingredient — see fdc-map.json, regenerated by scripts/fdc-sync.mjs.
 *
 * Pack + price here is the fallback used when a store's price table has no match
 * (rough Romanian shelf prices in RON). Real per-store prices live in prices.json.
 */

type Pack = [grams: number, price: number, label: string];
type FdcFood = { description: string; kcal: number; protein: number; carbs: number; fat: number; fiber: number };

/** Either a USDA link (fdcId) or, where no USDA record exists yet, an estimate per 100 g. */
type MapEntry = { fdcId?: number; note?: string; estimate?: Nutrients };
const MAP = FDC_MAP as Record<string, MapEntry>;
const FOODS = FDC.foods as Record<string, FdcFood>;

function ing(
  id: string,
  name: string,
  aisle: Aisle,
  group: FoodGroup,
  allergens: Allergen[],
  pack: Pack,
  shelfDays: number,
  extra: Partial<Pick<Ingredient, 'unit' | 'staple'>> = {},
): Ingredient {
  const ref = MAP[id];
  let per100: Nutrients;
  let fdc: Ingredient['fdc'];
  if (ref?.estimate) {
    per100 = { ...ref.estimate };
    fdc = { id: 0, description: 'Estimate, not USDA', note: ref.note };
  } else {
    const food = ref?.fdcId !== undefined ? FOODS[ref.fdcId] : undefined;
    if (!ref || ref.fdcId === undefined || !food) throw new Error(`No FoodData Central record for ${id} — add it to fdc-map.json and run scripts/fdc-sync.mjs`);
    per100 = { kcal: food.kcal, protein: food.protein, carbs: food.carbs, fat: food.fat, fiber: food.fiber };
    fdc = { id: ref.fdcId, description: food.description, note: ref.note };
  }
  return {
    id,
    name,
    aisle,
    per100,
    fdc,
    group,
    allergens,
    pack: { grams: pack[0], price: pack[1], label: pack[2] },
    shelfDays,
    ...extra,
  };
}

